    rdfs:comment "The description of invoice details (terms, payment, etc.)." .

#################################################################
# General Class Axioms, Restrictions, and Equivalence
#################################################################

# BuyerRole and SellerRole as equivalent classes for reasoning
:BuyerRole owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      :Role
      [ a owl:Restriction ;
        owl:onProperty :isRoleInvolvementOf ;
        owl:someValuesFrom [
          a owl:Restriction ;
          owl:onProperty :hasRole ;
          owl:hasValue :BuyerRole
        ]
      ]
    )
] .

:SellerRole owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      :Role
      [ a owl:Restriction ;
        owl:onProperty :isRoleInvolvementOf ;
        owl:someValuesFrom [
          a owl:Restriction ;
          owl:onProperty :hasRole ;
          owl:hasValue :SellerRole
        ]
      ]
    )
] .

# Invoice must have at least one buyer and one seller involvement, at least one item, invoice number, and invoice amount
:Invoice rdfs:subClassOf
    [ a owl:Restriction ;
      owl:onProperty :involvesOrganization ;
      owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ;
      owl:onClass :InvoiceOrganizationInvolvement
    ] ,
    [ a owl:Restriction ;
      owl:onProperty :hasItem ;
      owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
      owl:onClass :InvoiceItem
    ] ,
    [ a owl:Restriction ;
      owl:onProperty :invoiceNumber ;
      owl:minCardinality "1"^^xsd:nonNegativeInteger
    ] ,
    [ a owl:Restriction ;
      owl:onProperty :invoiceAmount ;
      owl:minCardinality "1"^^xsd:nonNegativeInteger
    ] .

# InvoiceOrganizationInvolvement must have exactly one organization and one role
:InvoiceOrganizationInvolvement rdfs:subClassOf
    [ a owl:Restriction ;
      owl:onProperty :organization ;
      owl:cardinality "1"^^xsd:nonNegativeInteger
    ] ,
    [ a owl:Restriction ;
      owl:onProperty :hasRole ;
      owl:cardinality "1"^^xsd:nonNegativeInteger
    ] .

# InvoiceItem must have exactly one item and one net price
:InvoiceItem rdfs:subClassOf
    [ a owl:Restriction ;
      owl:onProperty :item ;
      owl:cardinality "1"^^xsd:nonNegativeInteger
    ] ,
    [ a owl:Restriction ;
      owl:onProperty :netPrice ;
      owl:cardinality "1"^^xsd:nonNegativeInteger
    ] .
